// For each article: read its page for the picture (og:image, or the site's
// featured image), download it, and pass it on to the dashboard, which keeps
// it (POST /api/items/{id}/picture). An article whose page has no picture,
// or whose page or picture cannot be read, is marked so it is not looked for
// again. See db/init/28-article-pictures.sql.
//
// One article at a time, with a pause between, so no site gets a burst.
const AGENT = 'DFP newsletter bot (HAMK student project)';
const MAX_BYTES = 10 * 1024 * 1024;
// A login or bot wall is not the article: its picture would be the site's.
const LOGIN_LIKE = /(log ?in|sign ?in|sign ?up|kirjaudu|rekister|access denied|just a moment|are you a robot)/i;

const unescape = (s) => String(s)
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
  .replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&#0?39;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&').trim();

// A <meta> tag's content, whichever order its attributes come in.
const meta = (html, names) => {
  for (const name of names) {
    const n = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const m = html.match(new RegExp(`<meta[^>]+(?:property|name)=["']${n}["'][^>]*?content=["']([^"']+)["']`, 'i'))
      || html.match(new RegExp(`<meta[^>]+content=["']([^"']+)["'][^>]*?(?:property|name)=["']${n}["']`, 'i'));
    if (m) return unescape(m[1]);
  }
  return null;
};

const findPicture = (html) => {
  let src = meta(html, ['og:image:secure_url', 'og:image', 'og:image:url', 'twitter:image', 'twitter:image:src']);
  if (!src) {
    const link = html.match(/<link[^>]+rel=["']image_src["'][^>]*href=["']([^"']+)["']/i);
    if (link) src = unescape(link[1]);
  }
  if (!src) {
    // WordPress marks the post's own picture.
    const img = html.match(/<img[^>]+class=["'][^"']*wp-post-image[^"']*["'][^>]*>/i);
    const s = img && img[0].match(/\ssrc=["']([^"']+)["']/i);
    if (s) src = unescape(s[1]);
  }
  return src;
};

// A picture's address as the page gives it, made whole.
const absolute = (src, page) => {
  if (/^https?:\/\//i.test(src)) return src;
  if (src.startsWith('//')) return `${(page.match(/^(https?:)/i) || ['', 'https:'])[1]}${src}`;
  const origin = (page.match(/^(https?:\/\/[^\/?#]+)/i) || [])[1];
  if (!origin) return src;
  if (src.startsWith('/')) return origin + src;
  return page.replace(/[?#].*$/, '').replace(/[^\/]*$/, '') + src;
};

// The picture's bytes as n8n hands them over: a Buffer, or, from a task
// runner, the same written out as { type: 'Buffer', data: [...] }.
const bytesOf = (body) => {
  if (!body || typeof body === 'string') return null;
  if (body.type === 'Buffer' && Array.isArray(body.data)) return Uint8Array.from(body.data);
  if (body instanceof ArrayBuffer) return new Uint8Array(body);
  if (ArrayBuffer.isView(body)) return new Uint8Array(body.buffer, body.byteOffset, body.byteLength);
  if (Array.isArray(body)) return Uint8Array.from(body);
  return null;
};

const toBase64 = (bytes) => {
  if (typeof Buffer !== 'undefined') return Buffer.from(bytes).toString('base64');
  let text = '';
  for (let i = 0; i < bytes.length; i += 1) text += String.fromCharCode(bytes[i]);
  return btoa(text);
};

const pause = (ms) => new Promise((resolve) => (typeof setTimeout === 'function' ? setTimeout(resolve, ms) : resolve()));

const out = [];
for (const item of $input.all()) {
  const { id, url } = item.json;
  const result = { id, outcome: 'none', picture_url: null, alt: null, data: null };
  try {
    const html = String(await this.helpers.httpRequest({
      url, timeout: 12000, json: false, headers: { 'User-Agent': AGENT },
    }));
    const title = (html.match(/<title[^>]*>([^<]*)<\/title>/i) || ['', ''])[1];
    let src = LOGIN_LIKE.test(title) ? null : findPicture(html);
    if (src) src = absolute(src, url);
    if (src && /^https?:\/\//i.test(src) && !/\.svg(\?|#|$)/i.test(src)) {
      result.picture_url = src;
      const answer = await this.helpers.httpRequest({
        url: src, timeout: 15000, encoding: 'arraybuffer', returnFullResponse: true, json: false,
        headers: { 'User-Agent': AGENT, Referer: url },
      });
      const type = String((answer.headers || {})['content-type'] || '');
      const bytes = bytesOf(answer.body);
      const size = bytes ? bytes.length : 0;
      if (!size || size > MAX_BYTES || (type && !/^image\//i.test(type)) || /svg/i.test(type)) {
        result.outcome = 'failed';
        result.error = `not a picture we can use: ${type || 'no type'}, ${size} bytes, ${typeof answer.body}`;
      } else {
        result.outcome = 'picture';
        result.alt = meta(html, ['og:image:alt', 'twitter:image:alt']);
        result.data = toBase64(bytes);
      }
    }
  } catch (e) {
    result.outcome = 'failed';
    // Shown in a failed run's data, for whoever looks into it.
    result.error = String((e && e.message) || e).slice(0, 300);
  }
  out.push({ json: result });
  await pause(400);
}
return out;
